/**
 * Custom Service Worker for RepCue PWA Update System
 * This file extends the Workbox-generated service worker with custom update handling
 */

// Import Workbox precaching
importScripts('https://storage.googleapis.com/workbox-cdn/releases/7.3.0/workbox-sw.js');

// Initialize Workbox
if (workbox) {
  console.log('🔧 Workbox is loaded');

  // Enable navigation preload for faster loading
  workbox.navigationPreload.enable();

  // Precache all assets generated by Vite build
  workbox.precaching.precacheAndRoute(self.__WB_MANIFEST);

  // Runtime caching strategies (matching Vite config)

  // Google Fonts
  workbox.routing.registerRoute(
    /^https:\/\/fonts\.googleapis\.com\/.*/i,
    new workbox.strategies.CacheFirst({
      cacheName: 'google-fonts-cache',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 10,
          maxAgeSeconds: 60 * 60 * 24 * 365, // 365 days
        }),
      ],
    })
  );

  workbox.routing.registerRoute(
    /^https:\/\/fonts\.gstatic\.com\/.*/i,
    new workbox.strategies.CacheFirst({
      cacheName: 'gstatic-fonts-cache',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 10,
          maxAgeSeconds: 60 * 60 * 24 * 365, // 365 days
        }),
      ],
    })
  );

  // Splash screens
  workbox.routing.registerRoute(
    /^\/splash\/.*/i,
    new workbox.strategies.CacheFirst({
      cacheName: 'splash-screens-cache',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 50,
          maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
        }),
      ],
    })
  );

  // UI Images (hero banner, icons, etc.)
  workbox.routing.registerRoute(
    /^\/images\/.*\.(png|jpg|jpeg|svg)$/i,
    new workbox.strategies.CacheFirst({
      cacheName: 'ui-images-cache',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 20,
          maxAgeSeconds: 60 * 60 * 24 * 90, // 90 days
        }),
      ],
    })
  );

  // Exercise videos
  workbox.routing.registerRoute(
    /^\/videos\/.*\.(mp4|webm|mov)$/i,
    new workbox.strategies.StaleWhileRevalidate({
      cacheName: 'exercise-videos-cache',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 60,
          maxAgeSeconds: 60 * 60 * 24 * 30, // 30 days
        }),
      ],
    })
  );

  // I18n locale files
  workbox.routing.registerRoute(
    /^\/locales\/.*\.json$/i,
    new workbox.strategies.StaleWhileRevalidate({
      cacheName: 'i18n-locales-cache',
      plugins: [
        new workbox.expiration.ExpirationPlugin({
          maxEntries: 50,
          maxAgeSeconds: 60 * 60 * 24 * 7, // 7 days
        }),
      ],
    })
  );

  // Navigation fallback
  workbox.routing.setDefaultHandler(
    new workbox.strategies.NetworkFirst({
      cacheName: 'default-cache',
    })
  );

  // Set up navigation route
  const navigationHandler = workbox.precaching.createHandlerBoundToURL('/index.html');
  const navigationRoute = new workbox.routing.NavigationRoute(navigationHandler, {
    denylist: [/^\/_/, /\/[^/?]+\.[^/]+$/],
  });
  workbox.routing.registerRoute(navigationRoute);

} else {
  console.error('❌ Workbox failed to load');
}

// Custom update handling for RepCue PWA Update System
let updateInProgress = false;

// Listen for messages from the updateService
self.addEventListener('message', (event) => {
  console.log('📨 Service worker received message:', event.data);

  if (event.data && event.data.type === 'SKIP_WAITING') {
    console.log('🚀 Received SKIP_WAITING message, updating service worker...');

    if (!updateInProgress) {
      updateInProgress = true;

      // Skip waiting and take control immediately
      self.skipWaiting();

      // Notify all clients about the update
      self.clients.matchAll().then(clients => {
        clients.forEach(client => {
          client.postMessage({
            type: 'SW_UPDATED',
            timestamp: new Date().toISOString()
          });
        });
      });
    }
  }

  if (event.data && event.data.type === 'GET_VERSION') {
    // Send version info back to client
    event.ports[0]?.postMessage({
      type: 'VERSION_INFO',
      version: self.registration?.scope || 'unknown',
      timestamp: new Date().toISOString()
    });
  }
});

// Handle service worker activation
self.addEventListener('activate', (event) => {
  console.log('✅ Service worker activated');

  event.waitUntil(
    (async () => {
      // Take control of all open tabs immediately
      if (self.registration?.navigationPreload) {
        await self.registration.navigationPreload.enable();
      }

      // Claim all clients immediately
      await self.clients.claim();

      // Notify all clients that the new service worker is active
      const clients = await self.clients.matchAll();
      clients.forEach(client => {
        client.postMessage({
          type: 'SW_ACTIVATED',
          timestamp: new Date().toISOString()
        });
      });

      console.log('🎯 Service worker now controlling all tabs');
    })()
  );
});

// Handle service worker installation
self.addEventListener('install', (event) => {
  console.log('⚡ Service worker installing...');

  // Don't skip waiting automatically - let updateService control this
  // This allows for coordinated updates across tabs
});

// Handle fetch events with enhanced error handling
self.addEventListener('fetch', (event) => {
  // Let Workbox handle all fetch events
  // Custom fetch handling can be added here if needed
});

// Handle periodic background sync (if supported)
self.addEventListener('sync', (event) => {
  console.log('🔄 Background sync triggered:', event.tag);

  if (event.tag === 'version-check') {
    event.waitUntil(
      // Trigger a version check when back online
      self.clients.matchAll().then(clients => {
        clients.forEach(client => {
          client.postMessage({
            type: 'TRIGGER_VERSION_CHECK',
            timestamp: new Date().toISOString()
          });
        });
      })
    );
  }
});

// Handle push notifications (for future update notifications)
self.addEventListener('push', (event) => {
  if (event.data) {
    try {
      const data = event.data.json();
      console.log('📬 Push notification received:', data);

      if (data.type === 'update-available') {
        // Notify clients about available update
        event.waitUntil(
          self.clients.matchAll().then(clients => {
            clients.forEach(client => {
              client.postMessage({
                type: 'UPDATE_NOTIFICATION',
                data: data,
                timestamp: new Date().toISOString()
              });
            });
          })
        );
      }
    } catch (error) {
      console.error('❌ Error handling push notification:', error);
    }
  }
});

// Cleanup and error handling
self.addEventListener('error', (event) => {
  console.error('❌ Service worker error:', event.error);
});

self.addEventListener('unhandledrejection', (event) => {
  console.error('❌ Service worker unhandled rejection:', event.reason);
});

console.log('🚀 RepCue PWA Service Worker loaded successfully');